import { AsciiOverlay } from "@/components/application/animations/ascii-overlay";

// This example uses Zeus demo images. Install the component's assets
// or pass your own image URLs. Setup: https://myzeusui.com/components/ascii-overlay/#installation

export default function Example() {
  return (
    <AsciiOverlay
      cellSize={8}
      opacity={0.9}
      jitter={0.35}
      reshuffleRate={0.6}
      whitening={0.7}
      glyphs={"1,x,0,X,*,#,@"}
      image="/assets/zeus/hero_profile_02.jpg"
      alt="Athlete profile with a colored ASCII overlay"
      scroll={false}
      keyColor="auto"
    />
  );
}

