files.content:
"use client";

import Engine from "./ascii-overlay-engine.jsx";
import css from "./ascii-overlay-styles";

export interface AsciiOverlayProps {
  className?: string;
  image?: string;
  video?: string;
  mask?: string;
  alt?: string;
  cellSize?: number;
  scroll?: boolean;
  glyphs?: string;
  threshLow?: number;
  threshHigh?: number;
  whitening?: number;
  opacity?: number;
  jitter?: number;
  reshuffleRate?: number;
  charGap?: number;
  shadeMix?: number;
  darkOpacity?: number;
  detailThresh?: number;
  detailStrength?: number;
  keyColor?: string;
  keyTolerance?: number;
  colorStep?: number;
  minRegion?: number;
  edgeFade?: number;
  edgePush?: number;
  debug?: boolean;
}

export function AsciiOverlay(props: AsciiOverlayProps) {
  return (
    <>
      <style>{css}</style>
      <Engine {...props} />
    </>
  );
}

import type { AsciiOverlayProps } from "./ascii-overlay";
import type { ComponentType } from "react";
declare const Engine: ComponentType<AsciiOverlayProps>;
export default Engine;
